function openSettings(category='home'){const me=current();if(!me)return;settingsReturnFocus=document.activeElement;renderSettingsAvatar($('settingsAvatar'),me);renderSettingsAvatar($('settingsAvatarLarge'),me);renderSettingsAvatar($('settingsAccountAvatar'),me);$('settingsUserName').textContent=me.name||'Seu perfil';$('settingsUserMeta').textContent='@'+me.username;$('settingsName').value=me.name||'';$('profileNote').textContent='';$('settingsAccountName').textContent=me.name||'—';$('settingsAccountMeta').textContent='@'+(me.username||'—');$('settingsAccountInfo').innerHTML=`<div class="setting-row"><div><b>Usuário</b><small>Identificador da conta</small></div><span class="settings-value">@${esc(me.username||'—')}</span></div>${me.email?`<div class="setting-row"><div><b>E-mail</b><small>Endereço associado à conta</small></div><span class="settings-value">${esc(me.email)}</span></div>`:''}`;$('settingsBack').classList.add('show');$('settingsBack').setAttribute('aria-hidden','false');document.body.classList.add('modal-open');renderSettingsThemeState();renderWorkspaceDefaultState();selectSettings(category);updatePhotoUI()}

function closeSettings(){const backTo=settingsReturnFocus;$('settingsBack').classList.remove('show');$('settingsBack').setAttribute('aria-hidden','true');$('settingsBackBtn').classList.add('hidden');$('settingsHome').classList.remove('hidden');$('settingsDetail').classList.add('hidden');document.body.classList.remove('modal-open');settingsReturnFocus=null;try{backTo?.focus?.()}catch{}}
function selectSettings(category){if(category==='home'){ $('settingsHome').classList.remove('hidden');$('settingsDetail').classList.add('hidden');$('settingsBackBtn').classList.add('hidden');$('settingsTitle').textContent='Configurações';return}$('settingsHome').classList.add('hidden');$('settingsDetail').classList.remove('hidden');$('settingsBackBtn').classList.remove('hidden');document.querySelectorAll('.settings-section').forEach(s=>s.classList.toggle('active',s.id==='settings-'+category));const labels={profile:'Perfil',theme:'Aparência',account:'Conta'};$('settingsTitle').textContent=labels[category]||'Configurações'}
function compressImage(file,max=1400){return new Promise((resolve,reject)=>{const reader=new FileReader();reader.onerror=()=>reject(new Error('Não foi possível ler a imagem.'));reader.onload=()=>{const img=new Image();img.onerror=()=>reject(new Error('Imagem inválida.'));img.onload=()=>{const scale=Math.min(1,max/Math.max(img.width,img.height));const w=Math.max(1,Math.round(img.width*scale)),h=Math.max(1,Math.round(img.height*scale));const canvas=document.createElement('canvas');canvas.width=w;canvas.height=h;const ctx=canvas.getContext('2d',{alpha:false});ctx.drawImage(img,0,0,w,h);resolve(canvas.toDataURL('image/jpeg',.9));};img.src=reader.result};reader.readAsDataURL(file)})}
async function saveProfile(){const me=current(),name=$('settingsName').value.trim();if(savingProfile)return;if(!name){$('profileNote').textContent='Digite um nome válido.';return}savingProfile=true;showSaveOverlay();const localAvatar=me.avatar,localSource=me.avatarSource,localCrop=me.avatarCrop;try{me.name=name;me.initials=name.split(/\s+/).filter(Boolean).slice(0,2).map(x=>x[0]).join('').toUpperCase()||'EU';if(state.users){const u=state.users.find(x=>x.id===me.id);if(u){u.name=me.name;u.initials=me.initials;u.avatar=me.avatar;u.avatarSource=me.avatarSource;u.avatarCrop=me.avatarCrop}}currentUser=me;if(online){const payload={name:me.name,initials:me.initials};if(isImageDataUrl(me.avatar)){payload.avatar=me.avatar;if(isImageDataUrl(me.avatarSource))payload.avatarSource=me.avatarSource;if(me.avatarCrop&&typeof me.avatarCrop==='object')payload.avatarCrop=me.avatarCrop}const r=await api('/api/settings',{method:'POST',body:JSON.stringify(payload)});if(r.state){state=r.state;const serverMe=state.users?.find(x=>x.id===me.id);if(serverMe){serverMe.avatar=serverMe.avatar||localAvatar;serverMe.avatarSource=serverMe.avatarSource||localSource;serverMe.avatarCrop=serverMe.avatarCrop||localCrop}}if(r.user)currentUser={...me,...r.user,avatar:r.user.avatar||localAvatar,avatarSource:r.user.avatarSource||localSource,avatarCrop:r.user.avatarCrop||localCrop}}else writeLocal();$('profileNote').textContent='Perfil atualizado.';renderApp();renderTopAccount();updatePhotoUI();openSettings('profile')}catch(e){$('profileNote').textContent='Não foi possível salvar o perfil na conta online.';writeLocal();renderApp();renderTopAccount();updatePhotoUI()}finally{savingProfile=false;hideSaveOverlay()}}
async function logout(){const logoutRequest=online?api('/api/logout',{method:'POST',keepalive:true}).catch(()=>{}):Promise.resolve();online=false;googleEnabled=false;currentUser=null;state=null;calendarMemberId=null;compareIds.clear();closeAppearance();showAuth();toast('Sessão encerrada.');await logoutRequest}
function showBoot(message='Verificando sua sessão e seus dados…',retry=false){$('authView').classList.add('hidden');$('appView').classList.add('hidden');$('mobileNav').classList.add('hidden');$('bootView').classList.remove('hidden');$('bootMessage').textContent=message;$('bootSpinner').classList.toggle('hidden',retry);$('retryBoot').classList.toggle('hidden',!retry)}
function showAuth(){$('bootView').classList.add('hidden');$('authView').classList.remove('hidden');$('appView').classList.add('hidden');$('mobileNav').classList.add('hidden');updateAppearance()}
function enterApp(){if(!currentUser||!state){showBoot('Não foi possível carregar a conta. Tente verificar a sessão novamente.',true);return}workspaceMode=state.workspaceMode||((state.group)?'group':'personal');$('bootView').classList.add('hidden');$('authView').classList.add('hidden');$('appView').classList.remove('hidden');$('mobileNav').classList.remove('hidden');calendarMemberId=currentUser.id;compareIds.clear();state.users.filter(u=>u.id!==currentUser.id).forEach(u=>compareIds.add(u.id));applyAccent(hex(localStorage.getItem(ACCENT_KEY))||DEFAULT_ACCENTS[theme()],false);renderApp()}

async function completeGoogleCallback(){const hash=new URLSearchParams(location.hash.replace(/^#/,'').replace(/^\?/,'').replace(/;/g,'&'));const accessToken=hash.get('access_token'),refreshToken=hash.get('refresh_token');if(!accessToken)return false;if(!refreshToken){toast('A sessão Google veio incompleta. Entre novamente.');clearInviteFromUrl();return false}try{const r=await api('/api/auth/google-session',{method:'POST',body:JSON.stringify({access_token:accessToken,refresh_token:refreshToken})});online=true;currentUser=r.user;const invite=new URLSearchParams(location.search).get('invite')||'';if(invite){await processInvite(invite)}else{const payload=await api('/api/state');state=payload.state;currentUser=payload.me||r.user}history.replaceState({},'',location.pathname);enterApp();return true}catch(e){toast(e.message||'Não foi possível concluir o login com Google.');clearInviteFromUrl();return false}}

async function boot(){showBoot();online=false;googleEnabled=false;const q=new URLSearchParams(location.search);if(q.get('auth_error')){const map={google_not_configured:'Login com Google ainda precisa ser configurado no servidor.',google_failed:'Não foi possível iniciar o login com Google.',google_state:'O convite de login expirou. Tente novamente.',session_not_configured:'A sessão persistente não está configurada no servidor.'};toast(map[q.get('auth_error')]||'Não foi possível entrar.');history.replaceState({},'',location.pathname)}try{if(q.get('auth_callback')&&await completeGoogleCallback())return;let payload=null;try{payload=await api('/api/state')}catch(e){if(e.status===401){online=true;try{const p=await api('/api/auth/providers');googleEnabled=Boolean(p.google&&p.persistentDatabase)}catch{googleEnabled=true}$('googleOption').classList.toggle('hidden',!googleEnabled);currentUser=null;state=null;showAuth();return}throw e}online=true;state=payload.state;currentUser=payload.me;workspaceMode=state.workspaceMode||'personal';$('googleOption').classList.remove('hidden');const invite=q.get('invite')||'';if(invite){try{await processInvite(invite)}catch(e){toast(e.message||'Não foi possível entrar na sala pelo convite.')}}enterApp()}catch(e){online=false;googleEnabled=false;currentUser=null;state=null;$('googleOption').classList.add('hidden');showBoot(e?.message||'Não foi possível carregar sua conta agora. Tente novamente.',true)}}

$('googleBtn').onclick=()=>{if(!online)return toast('O login com Google funciona na versão online.');if(!googleEnabled)return toast('O Google ainda não está configurado no servidor.');const invite=new URLSearchParams(location.search).get('invite')||'';location.href='/auth/google'+(invite?'?invite='+encodeURIComponent(invite):'')};
$('topAccount').onclick=()=>openSettings('home');$('workspaceDialogClose').onclick=closeWorkspaceDialog;$('workspaceDialogCancel').onclick=closeWorkspaceDialog;$('workspaceDialogBack').onclick=e=>{if(e.target===$('workspaceDialogBack'))closeWorkspaceDialog()};$('workspaceDialogSubmit').onclick=submitWorkspaceDialog;$('workspaceDefaultPersonal').onclick=()=>setDefaultWorkspace('personal');$('workspaceDefaultGroup').onclick=()=>setDefaultWorkspace('group');$('settingsClose').onclick=closeSettings;$('settingsBackBtn').onclick=()=>selectSettings('home');$('settingsBack').onclick=e=>{if(e.target===$('settingsBack'))closeSettings()};document.querySelectorAll('[data-settings]').forEach(b=>b.onclick=()=>selectSettings(b.dataset.settings));$('choosePhoto').onclick=()=>$('profilePhotoInput').click();$('profilePhotoPreview').onclick=()=>{const me=current();openCropper(me?.avatarSource||me?.avatar)};$('editPhoto').onclick=()=>{const me=current();openCropper(me?.avatarSource||me?.avatar)};$('removePhoto').onclick=()=>{const me=current();me.avatar=null;me.avatarSource=null;me.avatarCrop=null;if(state?.users){const u=state.users.find(x=>x.id===me.id);if(u){u.avatar=null;u.avatarSource=null;u.avatarCrop=null}}$('profilePhotoInput').value='';writeLocal();if(online)api('/api/settings',{method:'POST',body:JSON.stringify({avatar:null})}).catch(()=>{});renderApp();openSettings('profile');toast('Foto removida.')};$('profilePhotoInput').onchange=async e=>{const file=e.target.files?.[0];if(!file)return;if(!file.type.startsWith('image/'))return toast('Escolha uma imagem válida.');try{const source=await compressImage(file,1400);const me=current();me.avatarSource=source;me.avatarCrop=null;openCropper(source);$('profilePhotoInput').value=''}catch(err){toast(err.message)}};$('cropClose').onclick=closeCropper;$('cropCancel').onclick=closeCropper;$('cropBack').onclick=e=>{if(e.target===$('cropBack'))closeCropper()};$('cropReset').onclick=cropReset;$('cropZoom').oninput=e=>{cropZoom=Number(e.target.value)||1;renderCrop()};$('cropZoomOut').onclick=()=>{cropZoom=clamp(Number((cropZoom-.15).toFixed(2)),1,cropMax);renderCrop()};$('cropZoomIn').onclick=()=>{cropZoom=clamp(Number((cropZoom+.15).toFixed(2)),1,cropMax);renderCrop()};$('cropSave').onclick=applyCrop;$('cropStage').addEventListener('pointerdown',e=>{if(!cropImage)return;cropPointerId=e.pointerId;cropStartX=e.clientX;cropStartY=e.clientY;cropStartPanX=cropPanX;cropStartPanY=cropPanY;$('cropStage').classList.add('dragging');$('cropStage').setPointerCapture?.(e.pointerId)});$('cropStage').addEventListener('pointermove',e=>{if(e.pointerId!==cropPointerId)return;cropPanX=cropStartPanX+(e.clientX-cropStartX);cropPanY=cropStartPanY+(e.clientY-cropStartY);renderCrop()});['pointerup','pointercancel','pointerleave'].forEach(t=>$('cropStage').addEventListener(t,e=>{if(e.pointerId===cropPointerId){cropPointerId=null;$('cropStage').classList.remove('dragging')}}));window.addEventListener('resize',()=>{if($('cropBack').classList.contains('show'))renderCrop()});$('settingsBack').addEventListener('pointerdown',e=>{if(e.target!==$('settingsBack'))return});const settingsGrabber=$('settingsBack').querySelector('.settings-grabber');settingsGrabber.addEventListener('pointerdown',e=>{settingsDragStartY=e.clientY;settingsDragStartX=e.clientX;settingsDragging=true;$('settingsPanel')?.setPointerCapture?.(e.pointerId);settingsGrabber.setPointerCapture?.(e.pointerId)});settingsGrabber.addEventListener('pointermove',e=>{if(!settingsDragging)return;const dy=Math.max(0,e.clientY-settingsDragStartY);if(dy>0)$('settingsBack').querySelector('.settings-panel').style.transform=`translateY(${dy}px)`});['pointerup','pointercancel'].forEach(t=>settingsGrabber.addEventListener(t,e=>{if(!settingsDragging)return;const dy=Math.max(0,e.clientY-settingsDragStartY);settingsDragging=false;const panel=$('settingsBack').querySelector('.settings-panel');panel.style.transform='';if(dy>90)closeSettings()}));
$('saveProfile').onclick=saveProfile;$('settingsDark').onclick=()=>applyTheme('dark',true);$('settingsLight').onclick=()=>applyTheme('light',true);$('settingsThemeAppearance').onclick=()=>{closeSettings();toggleAppearance($('topTheme'))};$('settingsLogout').onclick=()=>{closeSettings();logout()};$('sideLogout').onclick=logout;$('cancelDay').onclick=closeDay;$('deleteDay').onclick=deleteDay;$('saveDay').onclick=saveDay;$('dayBack').onclick=e=>{if(e.target===$('dayBack'))closeDay()};document.addEventListener('keydown',e=>{if(e.key==='Escape'){if($('cropBack').classList.contains('show'))closeCropper();else if($('themePickerBack').classList.contains('show'))closeColorPicker();else if($('settingsBack').classList.contains('show'))closeSettings();else if($('appearance').classList.contains('show'))closeAppearance()}});

window.__openDay=openDay;window.__selectCalendar=id=>{calendarMemberId=id;renderCalendar()};window.__month=dir=>{calendarDate=new Date(calendarDate.getFullYear(),calendarDate.getMonth()+dir,1);renderCalendar()};window.__today=()=>{calendarDate=new Date();renderCalendar()};
$('retryBoot').onclick=boot;
boot();
